#include <cstdint>
#include <format>
#include <functional>
#include <iostream>
#include <string>
#include <utility>

struct Job {
  std::int64_t distance_m;
  std::int64_t waiting_s;
};

// The three rules, in whole cents. Money is never a double.
struct Flat {
  std::int64_t cents;
};
struct PerKilometre {
  std::int64_t cents_per_km;
};
struct PerMinute {
  std::int64_t cents_per_minute;
};

[[nodiscard]] constexpr std::int64_t price_of(Flat rule, const Job&) { return rule.cents; }
[[nodiscard]] constexpr std::int64_t price_of(PerKilometre rule, const Job& job) {
  return rule.cents_per_km * job.distance_m / 1000;
}
[[nodiscard]] constexpr std::int64_t price_of(PerMinute rule, const Job& job) {
  return rule.cents_per_minute * job.waiting_s / 60;
}

// The point of variation is one operation, so the strategy is one callable.
using Pricing = std::function<std::int64_t(const Job&)>;

class Quoter {
 public:
  explicit Quoter(Pricing pricing) : pricing_(std::move(pricing)) {}
  void use(Pricing pricing) { pricing_ = std::move(pricing); }
  [[nodiscard]] std::int64_t quote_cents(const Job& job) const { return pricing_(job); }

 private:
  Pricing pricing_;
};

[[nodiscard]] std::string shown(std::int64_t cents) { return std::format("{}.{:02}", cents / 100, cents % 100); }

int main() {
  const Job job{.distance_m = 7400, .waiting_s = 320};
  Quoter quoter(Pricing{[](const Job& j) { return price_of(Flat{.cents = 950}, j); }});
  std::cout << std::format("flat:          {}\n", shown(quoter.quote_cents(job)));

  quoter.use([](const Job& j) { return price_of(PerKilometre{.cents_per_km = 120}, j); });
  std::cout << std::format("per kilometre: {}\n", shown(quoter.quote_cents(job)));

  quoter.use([](const Job& j) { return price_of(PerMinute{.cents_per_minute = 45}, j); });
  std::cout << std::format("per minute:    {}\n", shown(quoter.quote_cents(job)));
}

