// The deleter is a template parameter of unique_ptr: one Strategy, fixed at compile time.
struct FileCloser {
  void operator()(std::FILE* file) const noexcept { std::fclose(file); }
};

using ClosingFn = void (*)(std::FILE*);

[[nodiscard]] std::string joined(std::span<const int> values) {
  std::string out;
  for (const int value : values) out += std::format("{}{}", out.empty() ? "" : " ", value);
  return out;
}

int main() {
  std::vector<int> ranges_mm{4100, 380, 1250, 90, 2600};

  std::ranges::sort(ranges_mm);  // std::ranges::less, the default comparison
  std::cout << std::format("default:          {}\n", joined(ranges_mm));

  std::ranges::sort(ranges_mm, std::ranges::greater{});
  std::cout << std::format("greater:          {}\n", joined(ranges_mm));

  std::ranges::sort(ranges_mm, {}, [](int mm) { return std::abs(mm - 1000); });
  std::cout << std::format("closest to 1000:  {}\n", joined(ranges_mm));

  std::cout << std::format("unique_ptr<int>:                       {} bytes\n", sizeof(std::unique_ptr<int>));
  std::cout << std::format("unique_ptr<FILE, FileCloser>:          {} bytes\n",
                           sizeof(std::unique_ptr<std::FILE, FileCloser>));
  std::cout << std::format("unique_ptr<FILE, void(*)(FILE*)>:      {} bytes\n",
                           sizeof(std::unique_ptr<std::FILE, ClosingFn>));
  std::cout << std::format("unique_ptr<FILE, std::function<...>>:  {} bytes\n",
                           sizeof(std::unique_ptr<std::FILE, std::function<void(std::FILE*)>>));
}

struct Clamp {  // the same body behind all four holders
  std::span<const std::int32_t> readings;
  std::int32_t min_mm;
  std::int32_t max_mm;
  mutable std::int64_t at = 0;
  [[nodiscard]] std::int32_t apply() const {
