#include <algorithm>
#include <cstdint>
#include <format>
#include <functional>
#include <iostream>
#include <memory>
#include <utility>

// The settings of each profile, one struct per profile, so no two numbers can be swapped.
struct Cautious {
  std::int32_t stop_below_mm;
  std::int32_t top_mm_s;
};
struct Nominal {
  std::int32_t stop_below_mm;
  std::int32_t top_mm_s;
};
struct Hold {
  std::int32_t speed_mm_s;
};

[[nodiscard]] constexpr std::int32_t speed_of(Cautious p, std::int32_t clearance_mm) {
  return clearance_mm < p.stop_below_mm ? 0 : std::min(clearance_mm / 4, p.top_mm_s);
}
[[nodiscard]] constexpr std::int32_t speed_of(Nominal p, std::int32_t clearance_mm) {
  return clearance_mm < p.stop_below_mm ? 0 : std::min(clearance_mm / 2, p.top_mm_s);
}
[[nodiscard]] constexpr std::int32_t speed_of(Hold p, std::int32_t) { return p.speed_mm_s; }

// 1. The strategy behind an interface: swappable at run time, open to profiles this file never saw.
class Profile {
 public:
  Profile() = default;
  Profile(const Profile&) = delete;
  Profile& operator=(const Profile&) = delete;
  virtual ~Profile() = default;
  [[nodiscard]] virtual std::int32_t speed_mm_s(std::int32_t clearance_mm) const = 0;
};

template <typename Settings>
class SettingsProfile final : public Profile {
 public:
  explicit SettingsProfile(Settings settings) : settings_(settings) {}
  [[nodiscard]] std::int32_t speed_mm_s(std::int32_t clearance_mm) const override {
    return speed_of(settings_, clearance_mm);
  }

 private:
  Settings settings_;
};

class OwningPlanner {
 public:
  explicit OwningPlanner(std::unique_ptr<Profile> profile) : profile_(std::move(profile)) {}
  void use(std::unique_ptr<Profile> profile) { profile_ = std::move(profile); }
  [[nodiscard]] std::int32_t speed_mm_s(std::int32_t clearance_mm) const {
    return profile_->speed_mm_s(clearance_mm);
  }

 private:
  std::unique_ptr<Profile> profile_;
};

// 2. The strategy as a value: swappable at run time, copyable, one operation only.
class CallablePlanner {
 public:
  explicit CallablePlanner(std::function<std::int32_t(std::int32_t)> profile) : profile_(std::move(profile)) {}
  void use(std::function<std::int32_t(std::int32_t)> profile) { profile_ = std::move(profile); }
  [[nodiscard]] std::int32_t speed_mm_s(std::int32_t clearance_mm) const { return profile_(clearance_mm); }

 private:
  std::function<std::int32_t(std::int32_t)> profile_;
};

// 3. The strategy as a template parameter: fixed where the planner is built, no indirect call.
template <typename Settings>
class StaticPlanner {
 public:
  explicit StaticPlanner(Settings settings) : settings_(settings) {}
  [[nodiscard]] std::int32_t speed_mm_s(std::int32_t clearance_mm) const {
    return speed_of(settings_, clearance_mm);
  }

 private:
  [[no_unique_address]] Settings settings_;
};

int main() {
  const Cautious cautious{.stop_below_mm = 800, .top_mm_s = 400};
  const Nominal nominal{.stop_below_mm = 400, .top_mm_s = 800};

  OwningPlanner owning(std::make_unique<SettingsProfile<Cautious>>(cautious));
  CallablePlanner callable([cautious](std::int32_t mm) { return speed_of(cautious, mm); });
  const StaticPlanner<Cautious> fixed(cautious);

  std::cout << "clearance  interface  function  template\n";
  for (const std::int32_t mm : {200, 600, 1500, 4000}) {
    std::cout << std::format("{:>9}  {:>9}  {:>8}  {:>8}\n", mm, owning.speed_mm_s(mm), callable.speed_mm_s(mm),
                             fixed.speed_mm_s(mm));
  }

  // The same two planners, now running the nominal profile. The third cannot change.
  owning.use(std::make_unique<SettingsProfile<Nominal>>(nominal));
  callable.use([nominal](std::int32_t mm) { return speed_of(nominal, mm); });
  std::cout << "after swapping to the nominal profile at run time:\n";
  for (const std::int32_t mm : {200, 600, 1500, 4000}) {
    std::cout << std::format("{:>9}  {:>9}  {:>8}  {:>8}\n", mm, owning.speed_mm_s(mm), callable.speed_mm_s(mm),
                             fixed.speed_mm_s(mm));
  }

  owning.use(std::make_unique<SettingsProfile<Hold>>(Hold{.speed_mm_s = 150}));
  std::cout << std::format("a tow test holds {} mm/s at 200 mm of clearance\n", owning.speed_mm_s(200));

  std::cout << std::format("sizeof: OwningPlanner {}, plus {} on the heap\n", sizeof(OwningPlanner),
                           sizeof(SettingsProfile<Cautious>));
  std::cout << std::format("sizeof: CallablePlanner {}\n", sizeof(CallablePlanner));
  std::cout << std::format("sizeof: StaticPlanner<Cautious> {}, StaticPlanner<Hold> {}\n",
                           sizeof(StaticPlanner<Cautious>), sizeof(StaticPlanner<Hold>));
}

#include <chrono>
#include <cstdint>
#include <format>
#include <functional>
#include <iostream>
#include <iterator>
#include <memory>
#include <optional>
#include <string>
#include <vector>

using namespace std::chrono_literals;

struct Run {
  std::string name;
  std::int64_t travelled_mm;
  std::chrono::milliseconds duration;
  std::int32_t collisions;
  std::int32_t max_lateral_error_mm;
  std::int32_t samples;
};

struct Verdict {
  bool passed;
  std::string reason;
};

// One settings struct per rule, so no two numbers can be swapped at the call.
struct NoContact {};
struct LateralWithin {
  std::int32_t max_error_mm;
};
struct FinishesWithin {
  std::chrono::milliseconds budget;
};

[[nodiscard]] std::optional<Verdict> judge(NoContact, const Run& run) {
  if (run.samples == 0) return std::nullopt;
  return Verdict{.passed = run.collisions == 0, .reason = std::format("contacts: {}", run.collisions)};
}

[[nodiscard]] std::optional<Verdict> judge(LateralWithin rule, const Run& run) {
  if (run.samples == 0) return std::nullopt;
  return Verdict{.passed = run.max_lateral_error_mm <= rule.max_error_mm,
                 .reason = std::format("worst offset {} mm, limit {} mm", run.max_lateral_error_mm, rule.max_error_mm)};
}

[[nodiscard]] std::optional<Verdict> judge(FinishesWithin rule, const Run& run) {
  if (run.samples == 0) return std::nullopt;
  return Verdict{.passed = run.duration <= rule.budget,
                 .reason = std::format("{} taken, budget {}", run.duration, rule.budget)};
}

// 1. The evaluators behind an interface.
class Evaluator {
 public:
  Evaluator() = default;
  Evaluator(const Evaluator&) = delete;
  Evaluator& operator=(const Evaluator&) = delete;
  virtual ~Evaluator() = default;
  [[nodiscard]] virtual std::optional<Verdict> judge(const Run& run) const = 0;
};

template <typename Rule>
class RuleEvaluator final : public Evaluator {
 public:
  explicit RuleEvaluator(Rule rule) : rule_(rule) {}
  [[nodiscard]] std::optional<Verdict> judge(const Run& run) const override { return ::judge(rule_, run); }

 private:
  [[no_unique_address]] Rule rule_;
};

// 2. The same evaluators as values.
using Judging = std::function<std::optional<Verdict>(const Run&)>;

[[nodiscard]] std::string shown(const std::optional<Verdict>& verdict) {
  if (!verdict) return "no samples";
  return std::format("{} ({})", verdict->passed ? "pass" : "FAIL", verdict->reason);
}

int main() {
  const LateralWithin lateral{.max_error_mm = 120};
  const FinishesWithin budget{.budget = 20s};

  std::vector<std::unique_ptr<Evaluator>> objects;
  objects.push_back(std::make_unique<RuleEvaluator<NoContact>>(NoContact{}));
  objects.push_back(std::make_unique<RuleEvaluator<LateralWithin>>(lateral));
  objects.push_back(std::make_unique<RuleEvaluator<FinishesWithin>>(budget));

  std::vector<Judging> callables{
      [](const Run& run) { return judge(NoContact{}, run); },
      [lateral](const Run& run) { return judge(lateral, run); },
      [budget](const Run& run) { return judge(budget, run); },
  };

  const std::vector<Run> runs{
      {.name = "straight_10m",
       .travelled_mm = 10'020,
       .duration = 18'400ms,
       .collisions = 0,
       .max_lateral_error_mm = 74,
       .samples = 920},
      {.name = "slalom",
       .travelled_mm = 12'300,
       .duration = 26'100ms,
       .collisions = 1,
       .max_lateral_error_mm = 310,
       .samples = 1305},
      {.name = "aborted", .travelled_mm = 0, .duration = 0ms, .collisions = 0, .max_lateral_error_mm = 0, .samples = 0},
  };

  for (const Run& run : runs) {
    std::cout << std::format("{}\n", run.name);
    for (std::ptrdiff_t k = 0; k < std::ssize(objects); ++k) {
      const std::string from_object = shown(objects[k]->judge(run));
      const std::string from_callable = shown(callables[k](run));
      std::cout << std::format("  rule {}: {:<44} agree: {}\n", k, from_object, from_object == from_callable);
    }
  }

  // Replacing one rule in a list that is already built.
  callables[1] = [](const Run& run) { return judge(LateralWithin{.max_error_mm = 400}, run); };
  std::cout << std::format("slalom under a 400 mm limit: {}\n", shown(callables[1](runs[1])));

  std::cout << std::format("sizeof one element: unique_ptr {}, function {}\n", sizeof(objects.front()),
                           sizeof(callables.front()));
  std::cout << std::format("sizeof each object on the heap: {}, {}, {}\n", sizeof(RuleEvaluator<NoContact>),
                           sizeof(RuleEvaluator<LateralWithin>), sizeof(RuleEvaluator<FinishesWithin>));
}

// The two modes the robot will ever have, in the one place that chooses.
enum class Mode { driving, towing };

[[nodiscard]] constexpr std::int32_t speed_mm_s(std::int32_t clearance_mm, Mode mode) {
  if (mode == Mode::towing) return 150;
  return clearance_mm < 800 ? 0 : std::min(clearance_mm / 4, 400);
}

#include <cstdint>
#include <format>
#include <iostream>

enum class ProfileKind { cautious, nominal, hold };

// A closed set, chosen by a switch. The hold profile arrived later and this was not updated.
[[nodiscard]] std::int32_t top_speed_mm_s(ProfileKind kind) {
  switch (kind) {
    case ProfileKind::cautious:
      return 400;
    case ProfileKind::nominal:
      return 800;
  }
  return 0;
}

int main() {
  std::cout << std::format("{}\n", top_speed_mm_s(ProfileKind::hold));
}

#include <cstdint>
#include <format>
#include <functional>
#include <iostream>
#include <utility>

class CallablePlanner {
 public:
  CallablePlanner() = default;  // built without a profile: this is the bug
  void use(std::function<std::int32_t(std::int32_t)> profile) { profile_ = std::move(profile); }
  [[nodiscard]] std::int32_t speed_mm_s(std::int32_t clearance_mm) const { return profile_(clearance_mm); }

 private:
  std::function<std::int32_t(std::int32_t)> profile_;
};

int main() {
  CallablePlanner planner;
  try {
    std::cout << std::format("speed at 1500 mm: {}\n", planner.speed_mm_s(1500));
  } catch (const std::bad_function_call& e) {
    std::cout << std::format("calling an empty std::function threw: {}\n", e.what());
  }

  planner.use([](std::int32_t mm) { return mm / 2; });
  std::cout << std::format("after use(): speed at 1500 mm is {}\n", planner.speed_mm_s(1500));
}
